hl.bind(mod .. " + " .. "SHIFT" .. " + " .. "V", hl.dsp.exec_cmd("cliphist list | rofi -dmenu -p Portapapeles -config " .. os.getenv("HOME") .. "/dotfiles/rofi/.config/rofi/config.rasi | cliphist decode | wl-copy"))

-- --- Ventanas ---

hl.bind(mod .. " + " .. "SHIFT" .. " + " .. "left", hl.dsp.window.move({ direction = "left" }))

hl.bind(mod .. " + " .. "SHIFT" .. " + " .. "right", hl.dsp.window.move({ direction = "right" }))

hl.bind(mod .. " + " .. "SHIFT" .. " + " .. "up", hl.dsp.window.move({ direction = "up" }))

hl.bind(mod .. " + " .. "SHIFT" .. " + " .. "down", hl.dsp.window.move({ direction = "down" }))

hl.bind(mod .. " + " .. "CTRL" .. " + " .. "left", hl.dsp.window.resize({ x = -40, y = 0, relative = true }), { repeating = true })

hl.bind(mod .. " + " .. "CTRL" .. " + " .. "right", hl.dsp.window.resize({ x = 40, y = 0, relative = true }), { repeating = true })

